import{d as g,C as n,o as d,c as h,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"离为火","description":"离为火，离上离下","frontmatter":{"title":"离为火","description":"离为火，离上离下","category":"hexagram","aliases":["离","离为火"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-30.md","filePath":"yijing/hexagrams/hexagram-30.md","lastUpdated":1787730063000}'),p={name:"yijing/hexagrams/hexagram-30.md"},y=g({...p,setup(u){const e=[{id:"li",term:"离",pinyin:"lí",meaning:"附着、附丽；也指火。离卦之德为「丽」——光明必须附着于某物才能存在。",context:"卦名。火是中虚的，问题只在「附着在什么上」。"},{id:"chupinniu",term:"畜牝牛",pinyin:"chù pìn niú",meaning:"畜养母牛。牝牛柔顺而能繁衍——喻依附对象要长期、稳定、有成长。",context:"卦辞点名离卦的答案：不是干草，是母牛。"},{id:"lvcuoran",term:"履错然",pinyin:"lǚ cuò rán",meaning:"脚步交错纷杂的样子。初九初入情境，节奏未稳。",context:"初九爻辞。"},{id:"jing",term:"敬",pinyin:"jìng",meaning:"谨慎敬畏。敬可辟咎。",context:"初九「敬之，无咎」。"},{id:"huangli",term:"黄离",pinyin:"huáng lí",meaning:"黄色的附着。黄为中正之色（土色居中），喻中正之道上的依附。",context:"六二「黄离，元吉」——全卦最好的状态。"},{id:"rize",term:"日昃",pinyin:"rì zè",meaning:"太阳西斜。昃，日偏西。日昃之离，光明将尽。",context:"九三爻辞。"},{id:"gufouerge",term:"鼓缶而歌",pinyin:"gǔ fǒu ér gē",meaning:"敲着瓦缶唱歌。缶是质朴陶器——主动参与、真实表达。",context:"九三面对日昃的两条路之一。"},{id:"dadie",term:"大耋",pinyin:"dà dié",meaning:"耋为七八十岁老人，大耋指垂暮之年。",context:"九三「大耋之嗟」。"},{id:"jie",term:"嗟",pinyin:"jiē",meaning:"嗟叹、叹息。",context:"九三、六五皆有「嗟」。"},{id:"chutituoruo",term:"出涕沱若",pinyin:"chū tì tuó ruò",meaning:"眼泪流得像下雨。沱，滂沱。",context:"六五爻辞。"},{id:"qijieruo",term:"戚嗟若",pinyin:"qī jiē ruò",meaning:"悲伤叹息的样子。戚，悲伤。",context:"六五爻辞。"},{id:"zheshou",term:"折首",pinyin:"zhé shǒu",meaning:"斩其魁首。喻精准打击首恶。",context:"上九「有嘉折首」。"},{id:"huofeiqichou",term:"获匪其丑",pinyin:"huò fěi qí chǒu",meaning:"不抓获其同类。丑，类、同类——不扩大化。",context:"上九爻辞。"},{id:"jiming",term:"继明",pinyin:"jì míng",meaning:"光明相继。「继明照于四方」：光明延续不断、普照四方。",context:"象传。"}],r=[{position:"初九",type:"yang",text:"履错然，敬之，无咎。",xiang:"履错之敬，以辟咎也。",textModern:"脚步交错纷杂、节奏未稳，谨慎敬畏地对待它，就没有灾咎。",xiangModern:"脚步错乱之时的敬畏，正是为了避开灾咎。"},{position:"六二",type:"yin",text:"黄离，元吉。",xiang:"黄离元吉，得中道也。",textModern:"黄色（中正之色）的附着，大吉。",xiangModern:"黄离大吉，是因为得了中道。"},{position:"九三",type:"yang",text:"日昃之离，不鼓缶而歌，则大耋之嗟，凶。",xiang:"日昃之离，何可久也。",textModern:"太阳西斜时的附丽，不敲着瓦缶唱歌，就会发出垂老之人的嗟叹，凶。",xiangModern:"日西斜时的附丽，怎么会长久呢。"},{position:"九四",type:"yang",text:"突如其来如，焚如，死如，弃如。",xiang:"突如其来如，无所容也。",textModern:"突然而来的样子，像焚烧，像死亡，像被抛弃。",xiangModern:"突然而来，无处可容。"},{position:"六五",type:"yin",text:"出涕沱若，戚嗟若，吉。",xiang:"六五之吉，离王公也。",textModern:"泪流滂沱、悲伤嗟叹，却吉祥。",xiangModern:"六五的吉祥，在于附着于王公而得支撑。"},{position:"上九",type:"yang",text:"王用出征，有嘉折首，获匪其丑，无咎。",xiang:"王用出征，以正邦也。",textModern:"君王因此出征，值得嘉许的是斩其魁首、不牵连其同类，无咎。",xiangModern:"君王出征，是为了匡正邦国。"}];return(m,t)=>{const a=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),h("div",null,[i(a,{name:"离为火",fullName:"离为火",upper:"☲",lower:"☲",guaCi:"离，利贞，亨。畜牝牛，吉。",pinyin:["lí","wéi","huǒ"],element:"火",direction:"南",virtue:"丽",insight:"火虚中而丽，需附着而生——附干草一焚即尽，附母牛长明不熄。",guaSlug:"30liweihuo",lines:r}),t[0]||(t[0]=o('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>明两作，离。大人以继明照于四方。</p><p>两重光明相继升起（上离下离，明两作），就是离卦之象；大人由此领悟，要以不断延续的光明，照遍四方。</p><p>「明两作」「继明」的拆解——<strong>作</strong>是起、是兴，太阳日复一日地升起；<strong>继</strong>是相接、是传承，前一明未尽，后一明又起。光明不是一次性的绽放，是不间断的延续。</p><p>火为什么需要附着？因为火没有形体——光与热必须靠燃烧之物才能存在。离卦的智慧全在这两字里：<strong>要光明，先找到能持续燃烧的东西。</strong></p><p>分形结构：</p><ul><li>继明（两明相继）→ 微观：把热爱延续成日课，让光不熄灭</li><li>附着（火赖薪传）→ 宏观：找对依附的载体，让体系有柴可烧</li></ul><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>离，丽也。日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨。是以畜牝牛吉也。</p><p>逐句释义：</p><ul><li><strong>离，丽也</strong> —— 离就是附着。丽，依附、附丽。火是六十四卦中「附着」的化身。</li><li><strong>日月丽乎天，百谷草木丽乎土</strong> —— 日月附着于天，百谷草木附着于土。一切光明与生长，都建立在附着的对象之上。</li><li><strong>重明以丽乎正，乃化成天下</strong> —— 双重光明附着于正道，就能教化、成就天下。</li><li><strong>柔丽乎中正，故亨</strong> —— 以柔顺附着于中正，所以亨通。</li><li><strong>是以畜牝牛吉也</strong> —— 所以畜养牝牛吉祥。</li></ul><blockquote><p><strong>附着哲学</strong>：火是中虚的，它没有自己的形体，问题永远只有一个——<strong>附着在什么上</strong>。附着对了，光明才有根。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"火",guaSlug:"30liweihuo",glossary:e,items:r}),t[1]||(t[1]=o('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-履错然-敬之-无咎" tabindex="-1">初九 · 履错然，敬之，无咎 <a class="header-anchor" href="#初九-·-履错然-敬之-无咎" aria-label="Permalink to &quot;初九 · 履错然，敬之，无咎&quot;">​</a></h3><ul><li>位置：卦之初，阳居阳位，刚入火境</li><li><strong>履错然</strong> → 脚步交错纷杂，节奏未稳</li><li><strong>敬之</strong> → 谨慎敬畏地对待</li><li>小象：<strong>履错之敬，以辟咎也</strong>——错乱之时的敬畏，正是避咎之法</li></ul><p>初九刚燃起第一簇火，最容易乱：步子交错、四处张望，什么都想抓。此时的功课不是烧旺，是「敬」——敬畏每一步。光明之初，先有敬畏，后有中正。</p><blockquote><p>履错不是错，是对陌生处境的诚实；敬之，是把它踩稳的钥匙。</p></blockquote><h3 id="六二-·-黄离-元吉" tabindex="-1">六二 · 黄离，元吉 <a class="header-anchor" href="#六二-·-黄离-元吉" aria-label="Permalink to &quot;六二 · 黄离，元吉&quot;">​</a></h3><ul><li>位置：下卦之中，阴居阴位，得中得正</li><li><strong>黄离</strong> → 黄色的附着；黄为中正之色</li><li><strong>元吉</strong> → 大吉</li><li>小象：<strong>黄离元吉，得中道也</strong>——得了中道</li></ul><p>六二是全卦最好的状态：<strong>中正依附</strong>。黄是居中之色，火附于中正之道，光明温润而不灼人。从初九的「敬」到六二的「中」，是依附的进阶——敬畏起步，中正落地。「畜牝牛」在此兑现：六二就是那头母牛——长期、稳定、有成长，稳稳地附于正道。</p><blockquote><p>黄离元吉：依附的姿态对了，光明自己会长。</p></blockquote><h3 id="九三-·-日昃之离-不鼓缶而歌-则大耋之嗟-凶" tabindex="-1">九三 · 日昃之离，不鼓缶而歌，则大耋之嗟，凶 <a class="header-anchor" href="#九三-·-日昃之离-不鼓缶而歌-则大耋之嗟-凶" aria-label="Permalink to &quot;九三 · 日昃之离，不鼓缶而歌，则大耋之嗟，凶&quot;">​</a></h3><ul><li>位置：下卦之顶，阳居阳位，日过中天</li><li><strong>日昃之离</strong> → 太阳西斜，光明将尽</li><li><strong>不鼓缶而歌，则大耋之嗟</strong> → 不敲着瓦缶唱歌，就会垂老嗟叹</li><li>小象：<strong>日昃之离，何可久也</strong>——这种附丽怎么会长久</li></ul><p>「日中则昃」，火的鼎盛期终会过去。衰减到来时只有两条路：<strong>鼓缶而歌</strong>（主动参与、真实表达），或<strong>大耋之嗟</strong>（哀叹老之将至）。「缶」是质朴的瓦器——不装高雅、不必盛装，敲着粗陶唱歌，是衰减期最真实的活法。光明衰减不可怕，可怕的是只剩嗟叹。</p><blockquote><p>日昃不可免，鼓缶可自选。在衰减里主动歌唱，就是把余烬续成微光。</p></blockquote><h3 id="九四-·-突如其来如-焚如-死如-弃如" tabindex="-1">九四 · 突如其来如，焚如，死如，弃如 <a class="header-anchor" href="#九四-·-突如其来如-焚如-死如-弃如" aria-label="Permalink to &quot;九四 · 突如其来如，焚如，死如，弃如&quot;">​</a></h3><ul><li>位置：上卦之初，阳居阴位，不中不正</li><li><strong>突如其来如</strong> → 突然而来的样子</li><li><strong>焚如，死如，弃如</strong> → 像焚烧、像死亡、像被抛弃</li><li>小象：<strong>无所容也</strong>——无处可容</li></ul><p>九四是全卦的警示。火一旦失去附着、独自狂烧，就变成「突如其来」——来势凶猛，却<strong>无处可容</strong>，最终焚如、死如、弃如。这是过度消耗、不可持续的结局：燃烧需要柴，九四把自己当柴烧空了。火焰凶猛不是问题，没有可持续的附着才是。</p><blockquote><p>焚如死如弃如：不是火太猛，是柴烧空了。</p></blockquote><h3 id="六五-·-出涕沱若-戚嗟若-吉" tabindex="-1">六五 · 出涕沱若，戚嗟若，吉 <a class="header-anchor" href="#六五-·-出涕沱若-戚嗟若-吉" aria-label="Permalink to &quot;六五 · 出涕沱若，戚嗟若，吉&quot;">​</a></h3><ul><li>位置：君位，阴居阳位，以柔居尊</li><li><strong>出涕沱若</strong> → 泪流如雨</li><li><strong>戚嗟若</strong> → 悲伤嗟叹</li><li>小象：<strong>六五之吉，离王公也</strong>——附着于王公而得助</li></ul><p>六五以柔居尊位，力量不足。它没有硬撑，而是坦然地哭、坦然地示弱——「出涕沱若，戚嗟若」。<strong>以柔克刚</strong>：承认不足不是失败，是获得支撑的第一步。正因为示弱，才得以「离王公」（附着于上九阳刚），所以吉。六五教的是：力量不够时，谦虚地承认，反而能借到力。</p><blockquote><p>出涕沱若却吉：以柔克刚，不在硬扛，在真示弱。</p></blockquote><h3 id="上九-·-王用出征-有嘉折首-获匪其丑-无咎" tabindex="-1">上九 · 王用出征，有嘉折首，获匪其丑，无咎 <a class="header-anchor" href="#上九-·-王用出征-有嘉折首-获匪其丑-无咎" aria-label="Permalink to &quot;上九 · 王用出征，有嘉折首，获匪其丑，无咎&quot;">​</a></h3><ul><li>位置：卦之极，阳居阴位，离明之极</li><li><strong>王用出征</strong> → 君王因此出征</li><li><strong>有嘉折首</strong> → 值得嘉许的是斩其魁首</li><li><strong>获匪其丑</strong> → 不抓获其同类（丑，类）</li><li>小象：<strong>王用出征，以正邦也</strong>——为了匡正邦国</li></ul><p>上九是离明之极，光照四野、看得清楚。但看清之后不是乱打，而是<strong>精准打击</strong>：只斩首恶（折首）、不扩大化（获匪其丑）。这呼应整卦的核心——火要附着于对的东西，力量也要落在对的靶子上：打蛇打七寸，不扫平一切。</p><blockquote><p>折首而不及丑：力量用在刀尖上，而不是扫平一切。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',26)),i(s,{title:"字词释义",items:[{term:"离",pinyin:["lí"],meaning:"附着、附丽；也指火。离卦之德为「丽」——光明必须附着于某物才能存在。"},{term:"丽",pinyin:["lì"],meaning:"附着、依附。日月丽乎天，百谷草木丽乎土。"},{term:"畜牝牛",pinyin:["chù","pìn","niú"],meaning:"畜养母牛。牝牛柔顺而能繁衍——喻依附对象要长期、稳定、有成长。"},{term:"履错然",pinyin:["lǚ","cuò","rán"],meaning:"脚步交错纷杂的样子。初九初入情境，节奏未稳。"},{term:"敬",pinyin:["jìng"],meaning:"谨慎敬畏。敬可辟咎。"},{term:"黄离",pinyin:["huáng","lí"],meaning:"黄色的附着。黄为中正之色，喻中正之道上的依附。"},{term:"昃",pinyin:["zè"],meaning:"日西斜。「日昃」即太阳偏西，光明将尽。"},{term:"缶",pinyin:["fǒu"],meaning:"瓦器、陶罐，质朴之物。"},{term:"鼓缶而歌",pinyin:["gǔ","fǒu","ér","gē"],meaning:"敲着瓦缶唱歌——主动参与、真实表达。"},{term:"耋",pinyin:["dié"],meaning:"老人，七八十岁。「大耋」指垂暮之年。"},{term:"嗟",pinyin:["jiē"],meaning:"嗟叹、叹息。"},{term:"沱",pinyin:["tuó"],meaning:"滂沱、雨下得很大。「出涕沱若」：泪流如雨。"},{term:"戚",pinyin:["qī"],meaning:"悲伤、忧愁。「戚嗟若」：悲伤叹息的样子。"},{term:"折首",pinyin:["zhé","shǒu"],meaning:"斩其魁首。喻精准打击首恶。"},{term:"丑",pinyin:["chǒu"],meaning:"类、同类。「获匪其丑」：不抓获其同类，不扩大化。"},{term:"继明",pinyin:["jì","míng"],meaning:"光明相继。「继明照于四方」：光明延续不断、普照四方。"}]}),t[2]||(t[2]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>离卦讲的是<strong>火如何存在</strong>。上离下离，两重光明，是六十四卦中最「亮」的一卦。但火的本质是「中虚」——火没有自己的形体，必须附着于燃烧物才能存在。所以离卦的全部问题只有一个：<strong>附着在什么上</strong>。</p><p>卦辞「离，利贞，亨。畜牝牛，吉」点明：附着要利贞（守正）、要亨（通达），而答案在「畜牝牛」——畜养母牛。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>离卦把「依附」讲透了。人生处处是依附：人依附于事业，企业依附于赛道，内容依附于平台，火焰依附于薪柴。离卦的价值，在于提出了一个极简的选择题：</p><ul><li><strong>干草</strong> —— 一点就着，一烧就尽（一次性）</li><li><strong>母牛</strong> —— 长期、稳定、有成长（可持续）</li></ul><p><strong>母牛 vs 干草</strong>，是离卦五把尺子中的第一把：火本身无好坏，看它附在什么上。附干草，绚烂一时；附母牛，长明不熄。</p><p>五个框架，串起整卦：</p><ol><li><strong>母牛 vs 干草</strong>——选对依附对象（卦辞）</li><li><strong>黄离元吉</strong>——中正 + 依附母牛（六二）</li><li><strong>鼓缶而歌</strong>——主动参与 + 真实表达（九三）</li><li><strong>以柔克刚</strong>——力量不足 → 谦虚成长（六五）</li><li><strong>精准打击</strong>——折首 + 不扩大化（上九）</li></ol><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>选对依附对象：先问「我附在什么上」——是干草（一次性的流量、一次性的项目），还是母牛（长期积累、可成长的事业与关系）？</li><li>中正依附：依附的姿态要「黄离」——守中、守正，不附于偏门</li><li>主动表达：日昃之时，鼓缶而歌——衰减期主动唱出来，不嗟叹</li><li>承认不足：力量不够时，出涕沱若——真诚示弱，反而得助</li><li>精准发力：折首获匪其丑——打首恶、不扩大化，力量用在刀尖</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻总览：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>处境</th><th>功课</th></tr></thead><tbody><tr><td>卦辞</td><td>离，利贞，亨。畜牝牛，吉</td><td>火要附着</td><td>选母牛，不选干草</td></tr><tr><td>初九</td><td>履错然，敬之，无咎</td><td>初入火境，节奏未稳</td><td>谨慎敬畏</td></tr><tr><td>六二</td><td>黄离，元吉</td><td>中正依附</td><td>依附的姿态要对</td></tr><tr><td>九三</td><td>日昃之离，不鼓缶而歌，则大耋之嗟</td><td>光明将尽</td><td>鼓缶而歌，主动表达</td></tr><tr><td>九四</td><td>突如其来如，焚如死如弃如</td><td>失去附着、独自狂烧</td><td>别把自己当柴烧完</td></tr><tr><td>六五</td><td>出涕沱若，戚嗟若，吉</td><td>以柔居尊、力不足</td><td>以柔克刚，真示弱</td></tr><tr><td>上九</td><td>王用出征，有嘉折首，获匪其丑</td><td>离明之极，看得清楚</td><td>精准打击，不扩大化</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>火是中虚的</strong>——火没有形体，问题只在「附着在什么上」</li><li><strong>母牛 vs 干草</strong>——依附对象要选长期、稳定、有成长的</li><li><strong>黄离元吉</strong>——中正 + 依附母牛，是最好的状态</li><li><strong>鼓缶而歌</strong>——衰减期主动参与 + 真实表达</li><li><strong>焚如死如弃如</strong>——过度消耗，不可持续</li><li><strong>以柔克刚</strong>——力量不足，则谦虚成长</li><li><strong>折首获匪其丑</strong>——精准打击，不扩大化</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>离卦像一张「依附体检表」，把昇哥手头的事一一对照：</p><ul><li><strong>羽毛球（初九、六二）</strong> → 刚学球时履错然：脚步交错、动作全乱；敬之——认真练每个基础动作。慢慢找到「黄离」：不追花哨，守住中正的基本功，反而进步最快。能长期打下去，因为选的是「母牛」——日拱一卒的练习，不是一次性的爆发。</li><li><strong>易思项目（六二、九三、九四）</strong> → 起步于「黄离元吉」：方向中正、依附对了人和事；热度过去后进入「日昃之离」，需要鼓缶而歌——主动输出、真实表达；也差点走进九四的「突如其来」：想一把烧旺、过度消耗，最后靠回到可持续的节奏，躲开了焚如之象。</li><li><strong>学电子琴（九三鼓缶而歌）</strong> → 学琴不为考级，正是日昃之时敲缶而歌：水平不高，但主动弹、真实表达，光就不衰减。</li><li><strong>学习新技术（六五、上九）</strong> → 初学新东西力量不足，出涕沱若——承认自己不会、真诚求教，反而学得快（以柔克刚）；等到学明白，出手精准——只解决核心问题，不四面出击（折首获匪其丑）。</li></ul><p><strong>一句话收整卦</strong>：离卦教人<strong>选对附着之物</strong>——火本身无好坏，附干草则一焚即尽，附母牛则长明不熄。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：坎（第二十九卦）、晋（第三十五卦）</li><li>坎与离的连结：坎离相对——水与火、险与明、北与南。坎是至险，离是至明；坎教「守心过险」，离教「择物而附」。险中守心，方能见明；坎上离下，即成水火既济（第六十三卦）。</li><li>离与晋的连结：晋卦「明出地上」——火地晋，光明升出地面，讲自昭明德；离卦「明两作」——两明相继，讲继明照于四方。晋是「光升上来」，离是「光续下去」。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',23))])}}});export{x as __pageData,y as default};
